setMethod('$', '_p_datamunge__LMM', function(x, name)

{
  accessorFuns = list('formula_text' = LMM_formula_text, 'group_variable' = LMM_group_variable, 'has_random_intercept' = LMM_has_random_intercept, 'random_effect_names' = LMM_random_effect_names, 'is_reml' = LMM_is_reml, 'observations' = LMM_observations, 'num_groups' = LMM_num_groups, 'rank' = LMM_rank, 'coefficients' = LMM_coefficients, 'coefficient_names' = LMM_coefficient_names, 'standard_errors' = LMM_standard_errors, 'z_values' = LMM_z_values, 'p_values' = LMM_p_values, 'fitted_values' = LMM_fitted_values, 'residuals' = LMM_residuals, 'residual_variance' = LMM_residual_variance, 'residual_std_dev' = LMM_residual_std_dev, 'random_effect_std_devs' = LMM_random_effect_std_devs, 'random_effect_correlation' = LMM_random_effect_correlation, 'group_labels' = LMM_group_labels, 'random_effects_for_group' = LMM_random_effects_for_group, 'log_likelihood' = LMM_log_likelihood, 'deviance' = LMM_deviance, 'aic' = LMM_aic, 'bic' = LMM_bic, 'summary' = LMM_summary, 'print_summary' = LMM_print_summary, 'predict' = LMM_predict);
  ;        idx = pmatch(name, names(accessorFuns));
  if(is.na(idx)) 
  return(callNextMethod(x, name));
  f = accessorFuns[[idx]];
  function(...){
    f(x, ...)
  };
}


);
