# Start of new_GLMM

`GLMM__SWIG_0` = function(data, formula, family, max_iterations, tol, de_population_size, de_max_generations, theta_bound, seed)
{
  if (inherits(data, "ExternalReference")) data = slot(data,"ref"); 
  formula = as(formula, "character"); 
  family = as(family, "character"); 
  max_iterations = as.integer(max_iterations);
  
  if(length(max_iterations) > 1) {
    warning("using only the first element of max_iterations");
  };
  
  
  de_population_size = as.integer(de_population_size);
  
  if(length(de_population_size) > 1) {
    warning("using only the first element of de_population_size");
  };
  
  de_max_generations = as.integer(de_max_generations);
  
  if(length(de_max_generations) > 1) {
    warning("using only the first element of de_max_generations");
  };
  
  
  seed = as.integer(seed);
  
  if(length(seed) > 1) {
    warning("using only the first element of seed");
  };
  
  ;ans = .Call('R_swig_new_GLMM__SWIG_0', data, formula, family, max_iterations, tol, de_population_size, de_max_generations, theta_bound, seed, PACKAGE='datamunger');
  ans <- if (is.null(ans)) ans
  else new("_p_datamunge__GLMM", ref=ans);
  
  reg.finalizer(ans@ref, delete_GLMM);
  ans
  
}

