  formula = as(formula, "character"); 
  priors = as.numeric(priors);
  ;ans = .Call('R_swig_new_LDA__SWIG_0', data, formula, priors, PACKAGE='datamunger');
  ans <- if (is.null(ans)) ans
  else new("_p_datamunge__LDA", ref=ans);
  
  reg.finalizer(ans@ref, delete_LDA);
  ans
  
}

