`LDA` <- function(...) {
  argtypes <- mapply(class, list(...));
  argv <- list(...);
  argc <- length(argtypes);
  f <- NULL;
# dispatch functions 2
  if (argc == 2) {
    if (( extends(argtypes[1], '_p_datamunge__DataFrame') && length(argv[[1]]) == 1 ) && ( is.character(argv[[2]]) && length(argv[[2]]) == 1 )) {
      f <- LDA__SWIG_1; 
    }
  } else if (argc == 3) {
    if (( extends(argtypes[1], '_p_datamunge__DataFrame') && length(argv[[1]]) == 1 ) && ( is.character(argv[[2]]) && length(argv[[2]]) == 1 ) && ( is.numeric(argv[[3]]) )) {
      f <- LDA__SWIG_0; 
    }
  };
  if (is.null(f)) {
    stop("cannot find overloaded function for LDA with argtypes (",toString(argtypes),")");
  };
  f(...);
}

