{
  accessorFuns = list('feature_names' = LLE_feature_names, 'observations' = LLE_observations, 'n_components' = LLE_n_components, 'kept_row_indices' = LLE_kept_row_indices, 'eigenvalues' = LLE_eigenvalues, 'dimension' = LLE_dimension, 'embedding_frame' = LLE_embedding_frame, 'summary' = LLE_summary, 'print_summary' = LLE_print_summary, 'plot_embedding' = LLE_plot_embedding, 'plot_embedding_grouped' = LLE_plot_embedding_grouped);
  ;        idx = pmatch(name, names(accessorFuns));
  if(is.na(idx)) 
  return(callNextMethod(x, name));
  f = accessorFuns[[idx]];
  function(...){
    f(x, ...)
  };
}


);
# end of accessor method for datamunge::LLE
