    warning("using only the first element of early_exaggeration_iterations");
  };
  
  
  
  momentum_switch_iteration = as.integer(momentum_switch_iteration);
  
  if(length(momentum_switch_iteration) > 1) {
    warning("using only the first element of momentum_switch_iteration");
  };
  
  metric = as(metric, "character"); 
  seed = as.integer(seed);
  
  if(length(seed) > 1) {
    warning("using only the first element of seed");
  };
  
  ;ans = .Call('R_swig_new_TSNE__SWIG_0', data, feature_columns, n_components, perplexity, max_iterations, learning_rate, early_exaggeration, early_exaggeration_iterations, initial_momentum, final_momentum, momentum_switch_iteration, metric, seed, PACKAGE='datamunger');
  ans <- if (is.null(ans)) ans
  else new("_p_datamunge__TSNE", ref=ans);
  
  reg.finalizer(ans@ref, delete_TSNE);
  ans
  
}

