`ARIMA` <- function(...) {
  argtypes <- mapply(class, list(...));
  argv <- list(...);
  argc <- length(argtypes);
  f <- NULL;
# dispatch functions 2
  if (argc == 1) {
    if ( is.numeric(argv[[1]]) ) {
      f <- ARIMA__SWIG_1; 
    }
  } else if (argc == 2) {
    if (( is.numeric(argv[[1]]) ) && ( extends(argtypes[2], '_p_datamunge__stats__ARIMAOptions') && length(argv[[2]]) == 1 )) {
      f <- ARIMA__SWIG_0; 
    }
  };
  if (is.null(f)) {
    stop("cannot find overloaded function for ARIMA with argtypes (",toString(argtypes),")");
  };
  f(...);
}

