`PSO` <- function(...) {
  argtypes <- mapply(class, list(...));
  argv <- list(...);
  argc <- length(argtypes);
  f <- NULL;
# dispatch functions 2
  if (argc == 0) {
    f <- PSO__SWIG_1; 
  } else if (argc == 1) {
    if ( extends(argtypes[1], '_p_datamunge__optim__PSOOptions') && length(argv[[1]]) == 1 ) {
      f <- PSO__SWIG_0; 
    }
  };
  if (is.null(f)) {
    stop("cannot find overloaded function for PSO with argtypes (",toString(argtypes),")");
  };
  f(...);
}

