`DifferentialEvolution` <- function(...) {
  argtypes <- mapply(class, list(...));
  argv <- list(...);
  argc <- length(argtypes);
  f <- NULL;
# dispatch functions 2
  if (argc == 0) {
    f <- DifferentialEvolution__SWIG_1; 
  } else if (argc == 1) {
    if ( extends(argtypes[1], '_p_datamunge__optim__DEOptions') && length(argv[[1]]) == 1 ) {
      f <- DifferentialEvolution__SWIG_0; 
    }
  };
  if (is.null(f)) {
    stop("cannot find overloaded function for DifferentialEvolution with argtypes (",toString(argtypes),")");
  };
  f(...);
}

